const cveId = $('When Executed by Another Workflow').first().json.cveId.trim().toUpperCase();
const cve = $input.first().json.vulnerabilities?.[0]?.cve;

if (!cve) {
  return [{
    json: {
      cveId,
      found: false,
      message: 'CVE not found in NVD. It may be reserved but not published yet.',
    },
  }];
}

// Prefer the newest CVSS version available
const pickMetric = (m = {}) =>
  m.cvssMetricV40?.[0] ?? m.cvssMetricV31?.[0] ?? m.cvssMetricV30?.[0] ?? null;
const metric = pickMetric(cve.metrics);

// Weakness types, e.g. CWE-502 (deserialization of untrusted data)
const cwes = [...new Set(
  (cve.weaknesses ?? [])
    .flatMap(w => w.description ?? [])
    .map(d => d.value)
    .filter(v => v.startsWith('CWE-'))
)];

// Affected products from CPE strings: cpe:2.3:a:<vendor>:<product>:<version>:...
const products = new Set();
for (const config of cve.configurations ?? []) {
  for (const node of config.nodes ?? []) {
    for (const match of node.cpeMatch ?? []) {
      if (!match.vulnerable) continue;
      const [, , , vendor, product] = match.criteria.split(':');
      products.add(`${vendor}:${product}`);
    }
  }
}

// Keep only the references that matter for triage
const references = cve.references ?? [];
const usefulTags = ['Exploit', 'Patch', 'Vendor Advisory', 'Mitigation'];
const keyReferences = references
  .filter(r => r.tags?.some(t => usefulTags.includes(t)))
  .slice(0, 5)
  .map(r => ({ url: r.url, tags: r.tags }));

return [{
  json: {
    cveId,
    found: true,
    status: cve.vulnStatus,
    published: cve.published,
    lastModified: cve.lastModified,
    description: cve.descriptions?.find(d => d.lang === 'en')?.value ?? '',
    cvssScore: metric?.cvssData?.baseScore ?? null,
    severity: metric?.cvssData?.baseSeverity ?? 'UNKNOWN',
    cvssVersion: metric?.cvssData?.version ?? null,
    cvssVector: metric?.cvssData?.vectorString ?? null,
    cwes,
    affectedProducts: [...products].slice(0, 10),
    affectedProductCount: products.size,
    hasExploitReference: references.some(r => r.tags?.includes('Exploit')),
    keyReferences,
  },
}];
